@block GroundPlanar begin
    @ports p::Power{Planar}, [frame = "world"]
    @equations p.f ~ [0.0, 0.0, 0.0]
    @causality p => (:flow_out, :fixed)
end

@block BadUnits begin
    @ports a::Power{Planar}, [frame = "world"]
    @parameters begin
        tau::Real = 1.0, [unit = "N*m", description = "Torque component"]
        F::Real = 1.0, [unit = "N", description = "Force component"]
    end
    @variables P::Real = 0.0, [state = :prefer]
    @equations begin
        ddt(P) ~ tau + F
        a.e[1] ~ tau
        a.e[2] ~ F
    end
end
